// All data and calculations are illustrative, session-only prototype state.
const $ = (s, root = document) => root.querySelector(s);
const money = n => 'Rs. ' + Math.round(Number(n) || 0).toLocaleString('en-PK');
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',wallet:'M3 6h16v14H3zM3 6V3h14v3M15 11h6v5h-6z',transactions:'M4 7h15l-4-4M20 17H5l4 4',budget:'M4 4h16v16H4zM4 9h16M9 9v11',goals:'M21 12a9 9 0 1 1-9-9M12 7a5 5 0 1 0 5 5M12 12l9-9M16 3h5v5',insights:'M4 20V10M10 20V4M16 20v-7M22 20H2',assets:'M3 20h18M5 20V9h4v11M10 20V4h4v16M15 20v-8h4v8',tax:'M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h5',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5zM20 2v4M18 4h4',bell:'M5 16h14l-2-3V9a5 5 0 0 0-10 0v4zM10 20h4',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1zM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14M5 12h14',arrow:'M4 12h16m-6-6 6 6-6 6',down:'m6 9 6 6 6-6',calendar:'M4 5h16v16H4zM4 10h16M8 3v4M16 3v4',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0zM5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8',scan:'M3 8V3h5M16 3h5v5M21 16v5h-5M8 21H3v-5M2 12h20M7 7h10v10H7',edit:'m4 15 11-11 5 5L9 20l-6 1zM12 7l5 5',food:'M4 3v6a3 3 0 0 0 6 0V3M7 3v19M17 3v19M17 3c-5 4-5 10 0 10',car:'m4 10 2-6h12l2 6M3 10h18v8H3zM5 18v3M19 18v3M6 14h2M16 14h2',bag:'M5 7h14l2 14H3zM8 8V5a4 4 0 0 1 8 0v3',briefcase:'M3 7h18v13H3zM8 7V3h8v4M3 12c6 4 12 4 18 0M12 12v4',shield:'M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7zM8 12l3 3 5-6',trend:'m3 17 6-6 4 4 8-11M15 4h6v6',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 6v6l4 2',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',menu:'M3 6h18M3 12h18M3 18h18',logout:'M9 3H3v18h6M9 12h12m-5-5 5 5-5 5',download:'M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-3a8 8 0 0 1 16 0v3',mail:'M3 5h18v14H3zM3 5l9 8 9-8',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 11v6M12 7v1',plane:'m3 10 18-7-7 18-3-8zM11 13 21 3',repeat:'M4 8a8 8 0 0 1 14-3l3 3M21 3v5h-5M20 16a8 8 0 0 1-14 3l-3-3M3 21v-5h5'};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.wallet}"/></svg>`;
const brand = () => `<a class="brand" href="#home"><span class="brand-mark">${icon('insights')}</span>HisabKetab <em>AI</em></a>`;
const btn = (label, action, type='', ico='') => `<button type="button" class="btn ${type}" data-action="${action}">${ico?icon(ico):''}${label}</button>`;
const link = (label, route, type='text-btn') => `<a href="#${route}" class="${type}">${label}${type==='text-btn'?icon('arrow'):''}</a>`;
const progress = (value, color='') => `<div class="progress"><i style="width:${Math.max(0,Math.min(100,value))}%;${color?'background:'+color:''}"></i></div>`;
const categories=['Food','Petrol/Transport','Shopping','Bills','Rent','Education','Healthcare','Entertainment','Salary','Freelance','Business','Investment','Other'];
const payments=['Cash','Bank','Card','Easypaisa','JazzCash','Other'];
const state={user:{name:'Abubakar Awan',email:'abubakar.awan@example.com',occupation:'Software Engineer',income:180000,incomeType:'Salary',language:'English'},budget:100000,weeklyBudget:25000,period:'Monthly',chart:'6 months',filter:{search:'',type:'All',category:'All',payment:'All',from:'',to:'',sort:'newest'},settings:'Personal Information',surplus:40000,allocation:[20000,12000,8000],allocated:false,preferences:{'Budget alerts':true,'Recurring payment reminders':true,'Goal updates':true,'Tax reminders':true},goals:[{id:1,name:'Emergency Fund',target:500000,saved:180000,date:'2027-06-01',priority:'High',icon:'shield'},{id:2,name:'New Car',target:2000000,saved:650000,date:'2028-01-01',priority:'Medium',icon:'car'},{id:3,name:'Vacation',target:250000,saved:90000,date:'2027-05-01',priority:'Low',icon:'plane'}],recurring:[{id:1,name:'Rent',amount:30000,date:'2026-11-01',confidence:98,status:'Confirmed'},{id:2,name:'Internet',amount:4000,date:'2026-10-12',confidence:96,status:'Detected'},{id:3,name:'Loan',amount:15000,date:'2026-10-15',confidence:92,status:'Detected'},{id:4,name:'Netflix',amount:2000,date:'2026-10-20',confidence:89,status:'Detected'}],assets:[{id:1,name:'Cash',amount:150000},{id:2,name:'Bank Accounts',amount:650000},{id:3,name:'Vehicle',amount:1500000},{id:4,name:'Investments',amount:900000},{id:5,name:'Property',amount:2000000}],liabilities:[{id:6,name:'Credit Card',amount:80000},{id:7,name:'Car Loan',amount:450000},{id:8,name:'Other Debt',amount:120000}],notifications:[{title:'Budget alert',text:'You have used 90% of your food budget.',icon:'budget',route:'budget'},{title:'Upcoming payment',text:'Your Rs. 15,000 loan payment is due on 15 October.',icon:'clock',route:'recurring'},{title:'A little insight',text:'Your transport expenses increased by 20%.',icon:'insights',route:'insights'},{title:'Tax profile needs attention',text:'Add your withholding certificate to complete your tax profile.',icon:'tax',route:'tax'},{title:'You’re making progress',text:'You are 36% toward your Emergency Fund.',icon:'goals',route:'goals'}],chat:[],taxDocs:[],admin:{categories:[...categories],rules:['Illustrative salary slab — 2026','Illustrative withholding credit'],templates:['Budget threshold reached','Upcoming recurring payment'],config:{'Recurring confidence threshold':85,'Budget alert threshold':85}}};
state.transactions=[{id:1,merchant:'Shell Petrol Station',category:'Petrol/Transport',amount:500,type:'Expense',payment:'Cash',date:'2026-10-07',person:'',notes:'Petrol refill',recurring:false},{id:2,merchant:'Lunch with Ali',category:'Food',amount:3000,type:'Expense',payment:'Card',date:'2026-10-07',person:'Ali',notes:'Total Rs. 6,000. Your share: Rs. 3,000.',recurring:false},{id:3,merchant:'Imtiaz Super Market',category:'Shopping',amount:4500,type:'Expense',payment:'Card',date:'2026-10-06',notes:'Weekly groceries',recurring:false},{id:4,merchant:'October Salary',category:'Salary',amount:180000,type:'Income',payment:'Bank',date:'2026-10-01',notes:'Monthly salary',recurring:true},{id:5,merchant:'Nayatel Internet',category:'Bills',amount:4000,type:'Expense',payment:'Bank',date:'2026-10-05',notes:'Internet bill',recurring:true},{id:6,merchant:'Home Rent',category:'Rent',amount:30000,type:'Expense',payment:'Bank',date:'2026-10-01',notes:'October rent',recurring:true},{id:7,merchant:'Car Loan',category:'Other',amount:15000,type:'Expense',payment:'Bank',date:'2026-10-02',notes:'Monthly installment',recurring:true},{id:8,merchant:'Earlier October expenses',category:'Other',amount:15400,type:'Expense',payment:'Cash',date:'2026-10-03',notes:'Aggregated sample expenses',recurring:false}];
const baselineTransactions=state.transactions.map(t=>({...t}));
const totals=()=>{const income=state.transactions.filter(t=>t.type==='Income').reduce((s,t)=>s+t.amount,0),expenses=state.transactions.filter(t=>t.type==='Expense').reduce((s,t)=>s+t.amount,0);return {income,expenses,balance:17900+income-expenses,remaining:state.budget-expenses};};
const netWorth=()=>state.assets.reduce((s,a)=>s+a.amount,0)-state.liabilities.reduce((s,a)=>s+a.amount,0);
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const categoryIcon=c=>c==='Food'?'food':c==='Petrol/Transport'?'car':c==='Salary'?'briefcase':c==='Shopping'?'bag':c==='Rent'?'home':'wallet';
let route='home',previousFocus=null,recordTimer=null,recordStarted=0,voiceStage='idle',simulationTimer=null;
const nav=[['home','home','Home'],['transactions','transactions','Transactions'],['budget','budget','Budget'],['goals','goals','Goals'],['insights','insights','Insights'],['assets','assets','Assets & Liabilities'],['tax','tax','Tax'],['assistant','spark','AI Assistant']];
const titles={home:'Overview',transactions:'Transactions',budget:'Budget',adaptive:'Budget Optimization',recurring:'Recurring Obligations',goals:'Financial Goals',allocation:'Goal Allocation',emergency:'Emergency Fund Planner',insights:'Insights',health:'Financial Health',assets:'Assets & Liabilities',tax:'Tax Overview',reasoning:'Tax Calculation',reconciliation:'Financial Reconciliation',report:'Tax-Ready Report',assistant:'AI Assistant',notifications:'Notifications',settings:'Profile & Settings',admin:'Admin Dashboard',scan:'Scan Receipt'};
function parentRoute(r){return ['adaptive','recurring'].includes(r)?'budget':['allocation','emergency'].includes(r)?'goals':r==='health'?'insights':['reasoning','reconciliation','report'].includes(r)?'tax':r;}
function render(){route=location.hash.slice(1)||'home';if(['splash','login','signup','otp','forgot','onboarding'].includes(route)){renderAuth();return;}if(!titles[route]){location.hash='home';return;}const active=parentRoute(route);$('#app').innerHTML=`<aside class="sidebar">${brand()}<div class="nav-label">WORKSPACE</div><nav aria-label="Main navigation">${nav.map(([r,i,n])=>`<a class="nav-item ${active===r?'active':''}" ${active===r?'aria-current="page"':''} href="#${r}">${icon(i)}${n}${r==='assistant'?'<span class="pill">NEW</span>':''}</a>`).join('')}</nav><div class="nav-label" style="margin-top:22px">PREFERENCES</div><a class="nav-item ${route==='notifications'?'active':''}" href="#notifications">${icon('bell')}Notifications<span class="badge pill">${state.notifications.filter(n=>!n.read).length}</span></a><a class="nav-item ${route==='settings'?'active':''}" href="#settings">${icon('settings')}Settings</a><div class="sidebar-bottom"><div class="sidebar-promo">${icon('spark')}<h3>A little smarter. Every day.</h3><p>Your money has a story.<br>Let HisabKetab AI help you read it.</p>${link('Meet your AI assistant','assistant')}</div><a href="#settings" class="profile"><span class="avatar">${esc(state.user.name.split(' ').map(n=>n[0]).join('').slice(0,2))}</span><span><strong>${esc(state.user.name)}</strong><small>Personal account</small></span>${icon('down')}</a></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb"><button class="icon-btn menu-toggle" aria-label="Open navigation" data-action="menu">${icon('menu')}</button><span>My workspace</span><span>/</span><strong>${titles[route]}</strong></div><div class="top-actions"><form id="global-search" class="search-wrap">${icon('search')}<input name="search" aria-label="Search transactions" placeholder="Search anything..."><kbd>⌘ K</kbd></form><a class="icon-btn" aria-label="Notifications" href="#notifications">${icon('bell')}${state.notifications.some(n=>!n.read)?'<i class="notification-dot"></i>':''}</a><span style="height:22px;border-left:1px solid var(--border)"></span><a class="avatar" href="#settings" aria-label="Your profile">AA</a></div></header><main class="content" id="main">${pages[route]()}<footer class="footer"><span>© 2026 HisabKetab AI. Made for a more confident you.</span><span>Frontend prototype · Sample data only <span style="display:inline;color:#498567">●</span></span></footer></main></div><nav class="bottom-nav" aria-label="Mobile navigation">${[['home','home','Home'],['transactions','transactions','Activity'],['budget','budget','Budget'],['assistant','spark','Ask AI'],['settings','settings','Settings']].map(([r,i,n])=>`<a href="#${r}" class="${active===r?'active':''}">${icon(i)}${n}</a>`).join('')}</nav>`;}
function heading(title,subtitle,actions='',eyebrow=''){return `<div class="page-heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function stat(label,value,foot,ico,featured=false){return `<div class="stat ${featured?'featured':''}"><div class="stat-label">${label}${icon(ico)}</div><div class="amount"><span>Rs.</span> ${Math.round(value).toLocaleString('en-PK')}</div><div class="stat-foot">${foot}</div></div>`;}
function cardHead(title,subtitle='',right=''){return `<div class="card-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${right}</div>`;}
function subnav(group){const groups={budget:[['budget','My budget'],['adaptive','AI optimization'],['recurring','Recurring obligations']],goals:[['goals','My goals'],['allocation','Goal allocation'],['emergency','Emergency fund']],insights:[['insights','Analytics'],['health','Financial health']],tax:[['tax','Overview'],['reasoning','How it’s calculated'],['reconciliation','Reconciliation'],['report','Tax-ready report']]};return `<nav class="subnav" aria-label="Section navigation">${groups[group].map(([r,l])=>`<a href="#${r}" class="${r===route?'active':''}">${l}</a>`).join('')}</nav>`;}
function barChart(){let inc=[135,150,142,166,158,180],exp=[67,93,78,110,95,totals().expenses/1000],labels=['May','Jun','Jul','Aug','Sep','Oct'];if(state.chart==='3 months'){inc=inc.slice(3);exp=exp.slice(3);labels=labels.slice(3);}return `<div class="chart-legend"><span><i class="dot"></i>Income</span><span><i class="dot" style="background:#a8c5b5"></i>Expenses</span></div><div class="bar-chart" role="img" aria-label="Monthly income and expenses in thousands of PKR. October income ${totals().income}, expenses ${totals().expenses}."><div class="chart-axis"><span>200k</span><span>150k</span><span>100k</span><span>50k</span><span>0</span></div>${inc.map((v,i)=>`<div class="bar-group"><div tabindex="0" class="bar" style="height:${v/2}%" title="${labels[i]} income: ${money(v*1000)}" aria-label="${labels[i]} income ${money(v*1000)}"></div><div tabindex="0" class="bar expense" style="height:${Math.min(100,exp[i]/2)}%" title="${labels[i]} expenses: ${money(exp[i]*1000)}" aria-label="${labels[i]} expenses ${money(exp[i]*1000)}"></div><small>${labels[i]}</small></div>`).join('')}</div>`;}
function donut(){return `<div class="donut-layout"><div class="donut" role="img" aria-label="Illustrative category spending: rent 34%, food 25%, shopping 17%, transport 14%, others 10%"><div class="donut-hole"><small>Total spent</small><strong>${money(totals().expenses).replace('Rs. ','')}</strong><small>PKR this month</small></div></div><div class="category-legend">${[['Rent',34,'#075c46'],['Food',25,'#6aa88a'],['Shopping',17,'#a9c9b5'],['Transport',14,'#7799de'],['Others',10,'#e0e8e2']].map(([n,v,c])=>`<div><i class="dot" style="background:${c}"></i>${n}<b>${v}%</b></div>`).join('')}</div></div>`;}
function transactionRows(limit=5){return [...state.transactions].sort((a,b)=>b.date.localeCompare(a.date)||b.id-a.id).slice(0,limit).map(t=>`<button class="transaction-row" data-action="transaction:${t.id}"><span class="category-icon ${t.type==='Income'?'green':t.category==='Bills'?'blue':''}">${icon(categoryIcon(t.category))}</span><span><strong>${esc(t.merchant)}</strong><small>${esc(t.category)} <span style="padding:0 4px">·</span> ${esc(t.payment)}</small></span><span class="row-amount ${t.type==='Income'?'income':''}"><strong>${t.type==='Income'?'+':'−'} ${money(t.amount)}</strong><small>${dateLabel(t.date)}</small></span></button>`).join('');}
function budgetValues(){const base=[['Food',18000,20000,'Food'],['Transport',9000,12000,'Petrol/Transport'],['Shopping',15000,10000,'Shopping'],['Bills',8000,12000,'Bills']];return base.map(([n,v,max,c])=>{const sum=arr=>arr.filter(t=>t.type==='Expense'&&t.category===c).reduce((s,t)=>s+t.amount,0);return[n,Math.max(0,v+sum(state.transactions)-sum(baselineTransactions)),state.categoryBudgets?.[n]||max];});}
function budgetRows(){return budgetValues().map(([n,v,m])=>`<div class="budget-row"><div class="split"><strong>${n}</strong><span>${money(v)} <span class="muted">/ ${money(m)}</span></span></div>${progress(v/m*100,v>m?'#cf8e65':'')}<div class="split"><small>${Math.round(v/m*100)}% used</small>${v>m?'<small style="color:#b96845">Over budget</small>':''}</div></div>`).join('');}
function home(){const t=totals();return heading(`Good Morning, ${esc(state.user.name.split(' ')[0])} <span style="font-size:24px">👋</span>`,'Here’s what’s happening with your money today.',`${btn('October 2026','date','','calendar')}${btn('Add transaction','quick-add','primary','plus')}`)+`<div class="stats">${stat('Available balance',t.balance,'<b>↗ 12.8%</b> vs. last month','wallet',true)}${stat('Monthly income',t.income,'<b>↗ 8.2%</b> vs. last month','trend')}${stat('Monthly expenses',t.expenses,'<b>↘ 4.1%</b> vs. last month','transactions')}${stat('Net worth',1850000+(netWorth()-4550000),'<b>↗ 6.4%</b> personal tracked wealth','assets')}</div><div class="dashboard-grid"><section class="card">${cardHead('Income vs. expenses','A little perspective on your cash flow.',`<select class="btn" aria-label="Chart period" id="chart-period"><option ${state.chart==='6 months'?'selected':''}>6 months</option><option ${state.chart==='3 months'?'selected':''}>3 months</option></select>`)}${barChart()}<div class="chart-note">${icon('trend')} Your income is keeping a healthy lead. Keep it up!</div></section><section class="card">${cardHead('Where your money goes','Your October spending, at a glance.',link('Details','insights'))}${donut()}<div class="summary-line">Illustrative category breakdown · October 2026</div></section></div><section class="ai-banner"><div class="ai-symbol">${icon('spark')}</div><div><h2>Your finances. A conversation away. <span class="pill blue">AI POWERED</span></h2><p>Log an expense, plan your next move, or simply ask a question.</p></div><div class="actions">${link('Ask HisabKetab AI','assistant','btn')}${btn('Scan receipt','scan','','scan')}<button class="mic-btn" aria-label="Record a voice expense" data-action="voice">${icon('mic')}</button></div></section><div class="dashboard-grid"><section class="card">${cardHead('Recent transactions','Your money on the move.',link('View all','transactions'))}${transactionRows()}</section><section class="card">${cardHead('Monthly budget','Make room for what matters.',link('Manage','budget'))}<div class="split"><span class="amount" style="font-size:24px;font-weight:750">${money(t.expenses)}</span><small>of ${money(state.budget)}</small></div>${budgetRows().slice(0)}<div class="summary-line split"><span>Left to spend</span><strong style="color:var(--green)">${money(t.remaining)}</strong></div></section></div><div class="three-grid"><section class="card">${cardHead('Coming up','Stay a step ahead.',link('See all','recurring'))}${state.recurring.filter(r=>r.status!=='Ignored').slice(1,3).map(r=>`<a class="transaction-row" href="#recurring"><span class="category-icon blue">${icon('repeat')}</span><span><strong>${r.name}</strong><small>${dateLabel(r.date)}</small></span><strong class="row-amount">${money(r.amount)}</strong></a>`).join('')}</section><section class="card">${cardHead('Financial health','Small habits. Stronger finances.',link('Explore','health'))}<div class="health"><div class="health-ring"><div><strong>78</strong><small>OUT OF 100</small></div></div><div><span class="pill">Looking healthy</span><p class="muted" style="font-size:11px;margin:9px 0">You’re building a<br>strong financial foundation.</p></div></div></section><section class="card">${cardHead('Saving for your future','One step closer every day.',link('View goals','goals'))}<div class="transaction-row"><span class="category-icon green">${icon('shield')}</span><strong>Emergency Fund</strong><span class="row-amount pill">${Math.round(state.goals[0].saved/state.goals[0].target*100)}%</span></div>${progress(state.goals[0].saved/state.goals[0].target*100)}<div class="split" style="font-size:11px"><strong>${money(state.goals[0].saved)}</strong><small>of ${money(state.goals[0].target)}</small></div><p class="muted" style="font-size:10px;margin:17px 0 0">A little saved today. More peace of mind tomorrow.</p></section></div>`;}
function transactions(){const f=state.filter;let arr=state.transactions.filter(t=>(!f.search||`${t.merchant} ${t.category} ${t.notes} ${t.person}`.toLowerCase().includes(f.search.toLowerCase()))&&(f.type==='All'||t.type===f.type)&&(f.category==='All'||t.category===f.category)&&(f.payment==='All'||t.payment===f.payment)&&(!f.from||t.date>=f.from)&&(!f.to||t.date<=f.to));arr.sort((a,b)=>f.sort==='amount'?b.amount-a.amount:f.sort==='oldest'?a.date.localeCompare(b.date):b.date.localeCompare(a.date)||b.id-a.id);return heading('Your money, in motion.','Every income. Every expense. All in one place.',btn('Add transaction','quick-add','primary','plus'))+`<section class="card"><div class="filters"><input aria-label="Search transactions" id="transaction-search" value="${esc(f.search)}" placeholder="Search transactions..."><select aria-label="Transaction type" data-filter="type">${options(['All','Income','Expense'],f.type,'All types')}</select><select aria-label="Category" data-filter="category">${options(['All',...categories],f.category,'All categories')}</select><select aria-label="Payment method" data-filter="payment">${options(['All',...payments],f.payment,'All payments')}</select><input type="date" aria-label="From date" data-filter="from" value="${f.from}"><input type="date" aria-label="To date" data-filter="to" value="${f.to}"><select aria-label="Sort transactions" data-filter="sort"><option value="newest" ${f.sort==='newest'?'selected':''}>Newest first</option><option value="oldest" ${f.sort==='oldest'?'selected':''}>Oldest first</option><option value="amount" ${f.sort==='amount'?'selected':''}>Highest amount</option></select>${btn('Reset','reset-filters')}</div><div class="split" style="margin-bottom:16px"><small>${arr.length} transactions</small><small>All amounts in PKR</small></div><div class="table-wrap"><table><thead><tr><th>Transaction</th><th>Date</th><th>Category</th><th>Payment</th><th style="text-align:right">Amount</th><th></th></tr></thead><tbody>${arr.map(t=>`<tr><td><button class="transaction-row" data-action="transaction:${t.id}"><span class="category-icon ${t.type==='Income'?'green':''}">${icon(categoryIcon(t.category))}</span><span><strong>${esc(t.merchant)}</strong>${t.recurring?'<small>Recurring</small>':''}</span></button></td><td>${dateLabel(t.date)}</td><td><span class="pill ${t.type==='Income'?'':'blue'}">${esc(t.category)}</span></td><td>${esc(t.payment)}</td><td style="text-align:right;font-weight:650;color:${t.type==='Income'?'var(--green)':'inherit'}">${t.type==='Income'?'+':'−'} ${money(t.amount)}</td><td><button class="icon-btn" aria-label="Edit ${esc(t.merchant)}" data-action="edit-transaction:${t.id}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table>${arr.length?'':'<div class="empty">No transactions match these filters.</div>'}</div></section>`;}
function budget(){const t=totals(),weekly=state.period==='Weekly',limit=weekly?state.weeklyBudget:state.budget,spent=weekly?t.expenses/4:t.expenses;return heading('A plan for every rupee.','Spend with intention. Save with confidence.',btn('Edit budget','edit-budget','primary','edit'))+subnav('budget')+`<div class="actions" style="margin-bottom:20px">${btn('Monthly','period:Monthly',!weekly?'primary':'')}${btn('Weekly','period:Weekly',weekly?'primary':'')}</div><div class="stats" style="grid-template-columns:repeat(3,1fr)">${stat(`${state.period} budget`,limit,'Your spending limit','budget',true)}${stat('Spent so far',spent,weekly?'Illustrative weekly share':'October 2026','transactions')}${stat('Remaining',limit-spent,'Keep a little breathing room','wallet')}</div><div class="two-grid"><section class="card">${cardHead('Category budgets','Monthly category allocations',btn('Set limits','category-budgets','','edit'))}${budgetRows()}</section><section class="feature-card"><span class="pill">${icon('spark')} AI BUDGET COACH</span><h2 style="margin-top:24px;font-size:24px">Make the rest of your month work for you.</h2><p>We consider your spending, upcoming bills, and savings target to suggest a practical daily limit.</p><div class="big-number">${money(dailyLimit())} <small>/ day</small></div>${link('Explore AI optimization','adaptive','btn')}</section></div><div class="notice">You are approaching your monthly budget limit. Shopping is ${money(Math.max(0,budgetValues()[2][1]-budgetValues()[2][2]))} over its category budget.</div>`;}
function dailyLimit(){return Math.max(0,Math.floor((totals().remaining-7600-5000)/12));}
function adaptive(){return heading('A smarter way to finish the month.','Adaptive Budget Optimization and Spending Forecasting')+subnav('budget')+`<div class="notice info">Illustrative forecast scenario: 12 days remaining. Calculations use your session budget, ${money(7600)} reserved obligations, and a ${money(5000)} savings target.</div><div class="two-grid"><section class="feature-card"><span class="pill">${icon('spark')} PERSONALIZED SPENDING PLAN</span><h2 style="font-size:24px;margin-top:25px">A little guidance.<br>A lot more peace of mind.</h2><p>You have 12 days remaining in this sample planning scenario. Your recommended discretionary spending limit is:</p><div class="big-number">${money(dailyLimit())} <small>/ day</small></div><div class="actions">${btn('View calculation','calculation')}${btn('Adjust budget','edit-budget')}</div></section><section class="card">${cardHead('Your spending forecast')} ${[['Current budget',money(state.budget)],['Spent to date',money(totals().expenses)],['Remaining budget',money(totals().remaining)],['Historical monthly spending',money(85000)],['Reserved recurring obligations',money(7600)],['Savings target',money(5000)],['Predicted spending',money(totals().expenses+2400*12)],['Recommended daily spending',money(dailyLimit())],['Risk level',totals().expenses+28800>state.budget?'Elevated — reduce discretionary spending':'Within plan']].map(([n,v])=>`<div class="list-line"><span class="muted">${n}</span><strong>${v}</strong></div>`).join('')}</section></div>`;}
function recurring(){return heading('Your regulars, recognized.','Automated Recurring Financial Obligation Discovery',btn('Add obligation','add-recurring','primary','plus'))+subnav('budget')+`<div class="ai-banner"><div class="ai-symbol">${icon('repeat')}</div><div><h2>Potential recurring obligations detected</h2><p>Simulated pattern matching across merchant, amount, and payment frequency. Review each suggestion before confirming.</p></div></div><div class="two-grid">${state.recurring.filter(r=>r.status!=='Ignored').map(r=>`<section class="card">${cardHead(r.name,'Monthly payment',`<span class="pill ${r.status==='Confirmed'?'':'blue'}">${r.status}</span>`)}<div class="big-number" style="font-size:29px">${money(r.amount)}</div><div class="list-line"><span>Next payment</span><strong>${dateLabel(r.date)}</strong></div><div class="list-line"><span>Pattern confidence</span><strong>${r.confidence}%</strong></div>${progress(r.confidence)}<p class="muted" style="font-size:12px">Similar payments detected across three previous months.</p><div class="actions">${r.status!=='Confirmed'?btn('Confirm',`confirm-recurring:${r.id}`,'primary','check'):''}${btn('Edit',`edit-recurring:${r.id}`,'','edit')}${btn('Ignore',`ignore-recurring:${r.id}`)}</div></section>`).join('')}</div>${state.recurring.some(r=>r.status==='Ignored')?`<p style="margin-top:20px">${btn('Restore ignored suggestions','restore-recurring')}</p>`:''}`;}
function goals(){return heading('Make someday a little closer.','Big dreams, broken into achievable steps.',btn('Create goal','create-goal','primary','plus'))+subnav('goals')+`<div class="three-grid" style="margin-top:0">${state.goals.map(g=>`<section class="card goal-card"><div class="split"><span class="category-icon green">${icon(g.icon)}</span><span class="pill ${g.priority==='High'?'':'blue'}">${g.priority} priority</span></div><h2>${esc(g.name)}</h2><div class="amount">${money(g.saved)}</div><small>saved of ${money(g.target)}</small>${progress(g.saved/g.target*100)}<div class="split"><small>${(g.saved/g.target*100).toFixed(1).replace('.0','')}% complete</small><small>${dateLabel(g.date)}</small></div><div class="actions" style="margin-top:24px">${btn('Add savings',`fund-goal:${g.id}`,'primary','plus')}${btn('Edit goal',`edit-goal:${g.id}`,'','edit')}</div></section>`).join('')}</div><div class="ai-banner"><div class="ai-symbol">${icon('spark')}</div><div><h2>Several goals. One thoughtful plan.</h2><p>Let your priorities guide how your monthly surplus is shared.</p></div><div class="actions">${link('Explore goal allocation','allocation','btn primary')}</div></div>`;}
function allocation(){return heading('Give every goal its fair share.','Financial Goal Conflict Resolution')+subnav('goals')+`<div class="two-grid"><section class="feature-card"><span class="pill">${icon('spark')} PRIORITY-BASED RECOMMENDATION</span><h2 style="font-size:23px;margin-top:25px">Build your safety net.<br>Keep your dreams moving.</h2><p>Available monthly surplus</p><div class="big-number">${money(state.surplus)}</div><p>Your emergency fund is prioritized because it is below the recommended level. The remaining amount supports your medium- and low-priority goals.</p><small>Simulated allocation · no money is transferred.</small></section><section class="card">${cardHead('Recommended allocation',state.allocated?'Saved as your monthly plan.':'A balanced plan for your next month.')}${state.goals.slice(0,3).map((g,i)=>`<div class="budget-row"><div class="split"><strong>${esc(g.name)}</strong><strong>${money(state.allocation[i])}</strong></div>${progress(state.allocation[i]/state.surplus*100)}<small>${g.priority} priority · ${Math.round(state.allocation[i]/state.surplus*100)}% of surplus</small></div>`).join('')}<div class="actions">${btn(state.allocated?'Recommendation accepted':'Accept recommendation','accept-allocation','primary','check')}${btn('Modify allocation','modify-allocation','','edit')}</div></section></div>`;}
function emergency(){const saved=state.goals[0].saved;return heading('Peace of mind, planned.','Personalized Emergency Fund Estimation')+subnav('goals')+`<div class="two-grid"><section class="card">${cardHead('Your financial foundation','Adjust your inputs to explore a sample recommendation.')}<form id="emergency-form">${field('Essential monthly expenses','essential','number',state.emergency?.essential||65000,'min="1" required')}${selectField('Income stability','stability',['High','Medium','Low'],state.emergency?.stability||'Medium')}${field('Recurring obligations','obligations','number',state.emergency?.obligations||35000,'min="0" required')}${btn('Update estimate','submit-form','primary','spark')}</form></section><section class="feature-card"><span class="pill">YOUR SAFETY NET</span><p style="margin-top:26px">Recommended emergency fund</p><div class="big-number">${money(state.emergency?.recommended||450000)}</div><p>Current emergency savings: <strong>${money(saved)}</strong></p>${progress(saved/(state.emergency?.recommended||450000)*100,'#c1dba5')}<p>${Math.round(saved/(state.emergency?.recommended||450000)*100)}% of your recommended fund</p><p>Your recommended emergency fund is based on your essential expenses, income stability, recurring financial obligations and current savings.</p><small>Sample method: (essential expenses + 50% of obligations) × stability reserve months, rounded up to Rs. 50,000. Medium stability uses 5 months.</small></section></div>`;}
function lineChart(values,color='#075c46',labels=['Mon','Tue','Wed','Thu','Fri','Sat','Sun']){const max=Math.max(...values)*1.15,points=values.map((v,i)=>`${30+i*480/(values.length-1)},${155-v/max*130}`).join(' ');return `<svg class="line-chart" viewBox="0 0 540 190" role="img" aria-label="${labels.map((l,i)=>l+': '+money(values[i])).join(', ')}"><path d="M30 25H515M30 70H515M30 115H515M30 155H515" stroke="#e9eeea" fill="none"/><polygon points="30,155 ${points} 510,155" fill="${color}" opacity=".06"/><polyline points="${points}" stroke="${color}" stroke-width="3" fill="none" stroke-linejoin="round"/>${values.map((v,i)=>`<circle tabindex="0" cx="${30+i*480/(values.length-1)}" cy="${155-v/max*130}" r="4" fill="${color}"><title>${labels[i]}: ${money(v)}</title></circle><text x="${30+i*480/(values.length-1)}" y="182" text-anchor="middle" font-size="10" fill="#6b7775">${labels[i]}</text>`).join('')}</svg>`;}
function insights(){return heading('See the bigger picture.','Turn everyday transactions into better financial decisions.',btn('Export data','export-data','','download'))+subnav('insights')+`<div class="two-grid"><section class="card">${cardHead('Monthly income vs. expenses','May – October 2026')}${barChart()}</section><section class="card">${cardHead('Spending by category','Illustrative monthly distribution')}${donut()}</section><section class="card">${cardHead('Weekly spending trend','Your spending is higher during weekends.')}${lineChart([1200,2100,900,1700,2400,4800,3600])}</section><section class="card">${cardHead('Savings trend','Your sample savings rate is 22%.')}${lineChart([16000,22000,19000,31000,34000,39600],'#557ae7',['May','Jun','Jul','Aug','Sep','Oct'])}</section><section class="card">${cardHead('Budget performance','Category spending against your limits')}${budgetRows()}</section><section class="card">${cardHead('A few things worth noticing','Sample insights from your spending patterns')} ${[['Food spending increased 18% this month.','Try a weekly meal budget to keep dining out in check.'],['Your savings rate is 22%.','Setting aside a little on payday builds consistency.'],['Transport is your second-largest discretionary expense.','Combine errands and keep an eye on fuel spending.'],['Your spending is higher during weekends.','Set a weekend allowance before Friday.']].map(([t,p])=>`<div class="list-line"><div><h3>${t}</h3><p class="muted" style="font-size:12px;margin:0">${p}</p></div></div>`).join('')}</section></div>`;}
function health(){return heading('Healthy money habits add up.','Your sample financial health score, explained.')+subnav('insights')+`<div class="two-grid"><section class="feature-card"><span class="pill">FINANCIAL HEALTH SCORE</span><div class="big-number" style="font-size:75px">78 <small>/ 100</small></div><h2>You’re on a healthy path.</h2><p>Your budget discipline and tax preparation are strong. Building your emergency savings is your next best step.</p>${link('Plan your emergency fund','emergency','btn')}</section><section class="card">${cardHead('What makes up your score')}${[['Budget Management',82],['Savings',71],['Debt Management',76],['Spending Stability',80],['Tax Readiness',84]].map(([n,v])=>`<div class="budget-row"><div class="split"><strong>${n}</strong><span>${v} / 100</span></div>${progress(v)}</div>`).join('')}</section></div><div class="notice info">Next steps: reduce shopping overspend, increase your emergency contribution by Rs. 5,000, and add your withholding certificate.</div>`;}
function assets(){return heading('Everything you own. Everything you owe.','A clearer picture of your complete financial position.',btn('Add item','add-asset','primary','plus'))+`<div class="stats" style="grid-template-columns:repeat(3,1fr)">${stat('Total assets',state.assets.reduce((s,a)=>s+a.amount,0),'Full wealth inventory','assets')}${stat('Total liabilities',state.liabilities.reduce((s,a)=>s+a.amount,0),'Outstanding balances','wallet')}${stat('Net worth',netWorth(),'Assets minus liabilities','trend',true)}</div><div class="notice info">This full wealth inventory includes property and vehicle values. Home shows a separate illustrative personal tracked-wealth baseline of Rs. 1,850,000.</div><div class="two-grid">${['assets','liabilities'].map(key=>`<section class="card">${cardHead(key==='assets'?'Your assets':'Your liabilities','Click an item to update its value.')} ${state[key].map(a=>`<button class="transaction-row" data-action="edit-asset:${key}:${a.id}"><span class="category-icon ${key==='assets'?'green':'blue'}">${icon(key==='assets'?'assets':'wallet')}</span><strong>${esc(a.name)}</strong><span class="row-amount">${money(a.amount)}</span>${icon('edit')}</button>`).join('')}</section>`).join('')}</div>`;}
const taxSample={income:2400000,deductions:100000,taxable:2300000,estimated:115000,withheld:90000,payable:25000};
function tax(){return heading('Tax season, with less guesswork.','Your Pakistan tax preparation workspace.',`${btn('Tax year 2026','tax-year','','calendar')}${link('Preview report','report','btn primary')}`)+subnav('tax')+`<div class="notice info">Illustrative tax scenario only. These sample rules and amounts are not verified tax advice or an official FBR calculation.</div><div class="stats">${stat('Total annual income',2400000,'All income sources','briefcase')}${stat('Taxable income',2300000,'After sample adjustments','tax')}${stat('Tax estimated',115000,'Illustrative rule set','budget')}${stat('Estimated tax payable',25000,'Rs. 90,000 already withheld','wallet',true)}</div><div class="two-grid"><section class="card">${cardHead('Your tax readiness','Keep your information together.',`<span class="pill">${state.taxDocs.length?92:82}% ready</span>`)}${progress(state.taxDocs.length?92:82)}${[['Income sources','Salary · Rs. 2,160,000 / Freelance · Rs. 240,000'],['Withholding tax','Rs. 90,000 · employer deduction'],['Relevant deductions','Rs. 100,000 · illustrative eligible adjustment'],['Calculation status','Draft estimate · review required']].map(([n,v])=>`<div class="list-line"><span>${n}</span><span class="muted">${v}</span></div>`).join('')}${link('How your tax was calculated','reasoning','btn')}</section><section class="card">${cardHead('Documents & missing information','Sample files remain in this session only.',btn('Add document','tax-document','','plus'))}<div class="list-line"><span>Annual income summary</span><span class="pill">Available</span></div><div class="list-line"><span>Withholding certificate</span><span class="pill ${state.taxDocs.length?'':'orange'}">${state.taxDocs.length?'Added':'Missing'}</span></div><div class="list-line"><span>CNIC / NTN information</span><a href="#settings" class="text-btn">Review profile</a></div>${state.taxDocs.map(d=>`<div class="list-line"><span>${esc(d)}</span><span class="pill">Local sample</span></div>`).join('')}<div class="notice">Review your tax profile and reconcile your closing wealth before preparing your report.</div>${link('Review wealth reconciliation','reconciliation')}</section></div>`;}
function reasoning(){const steps=[['Income','Salary Rs. 2,160,000 + freelance Rs. 240,000.','Sum of sample annual income sources',money(2400000)],['Income Classification','Salary and freelance income are identified separately for visibility.','Sample consolidated treatment for demonstration','Salary + freelance'],['Applicable Tax Rules','This prototype applies a simplified illustrative rule, not an official Pakistani tax slab.','Rule: DEMO-2026-01 · positive sample taxable income','Illustrative 5% rate'],['Deductions / Adjustments','A sample eligible adjustment reduces the illustrated income base. Eligibility is not verified.','Rs. 2,400,000 − Rs. 100,000',money(100000)],['Taxable Income','The remaining sample income after the illustrative adjustment.','Rs. 2,400,000 − Rs. 100,000',money(2300000)],['Applicable Tax Rate / Slab','A flat 5% demo rate is used to make the reasoning easy to follow. It is not an official slab.','Rule DEMO-2026-01 applies to this sample scenario','5% (illustrative)'],['Tax Liability','Multiply the sample taxable income by the demonstration rate.','Rs. 2,300,000 × 5%',money(115000)],['Withholding / Tax Credits','Sample employer withholding is credited against the estimate.','Rs. 90,000 sample tax withheld',money(90000)],['Estimated Tax Payable','Subtract withholding from the sample liability.','Rs. 115,000 − Rs. 90,000',money(25000)]];return heading('Understand every step.','Explainable Tax Rule Reasoning Engine')+subnav('tax')+`<div class="notice info">Tax year 2026 · Demonstration rules only · Not an official tax calculation</div><div style="max-width:880px;margin:auto">${steps.map(([n,p,c,r],i)=>`<details class="details-step" ${i===0?'open':''}><summary><span class="step-num">${i+1}</span>${n}</summary><p><strong>Why was this rule applied?</strong><br>${p}</p><div class="list-line"><span>Tax year / rule</span><strong>2026 / DEMO-2026-01</strong></div><div class="list-line"><span>Applicable condition / calculation</span><strong>${c}</strong></div><div class="list-line"><span>Result</span><strong>${r}</strong></div></details>`).join('')}${link('Continue to reconciliation','reconciliation','btn primary')}</div>`;}
function reconciliation(){const adj=state.adjustment||0,diff=3300000+adj-3250000;return heading('Make sure the numbers meet.','Review your sample annual wealth movement.')+subnav('tax')+`<div class="two-grid"><section class="card">${cardHead('Financial reconciliation','Separate illustrative annual wealth scenario')}${[['Opening wealth',2000000],['+ Annual income',2400000],['− Annual expenses',1100000],['+/− Adjustments',adj],['Expected closing wealth',3300000+adj],['Recorded closing wealth',3250000]].map(([n,v])=>`<div class="list-line"><span>${n}</span><strong>${money(v)}</strong></div>`).join('')}<div class="notice ${diff===0?'info':''}"><strong>Difference: ${money(diff)}</strong><br>${diff===0?'Balanced in this sample scenario':'Difference requires review'}</div>${btn('Review adjustment','adjust-reconciliation','','edit')}</section><section class="card">${cardHead('Where to look','Common reasons for a difference')} ${[['Missing transaction','transactions'],['Asset update required','assets'],['Liability update required','assets'],['Unrecorded income','transactions'],['Incorrect expense classification','transactions']].map(([n,r])=>`<div class="list-line">${link(n,r)}</div>`).join('')}<p class="muted" style="margin-top:25px;font-size:12px">Annual report values are an independent sample scenario. They are not calculated from the October transaction list.</p></section></div>`;}
function report(){return heading('Your financial year, together.','A draft report you can review and print.',`${btn('Preview report','preview-report','','tax')}${btn('Export PDF','print-report','primary','download')}`)+subnav('tax')+`<article class="card report" id="report"><div class="report-heading"><div class="split">${brand()}<span class="pill">TAX YEAR 2026</span></div><h1 style="margin-top:30px">Tax-Ready Report</h1><p class="muted">Prepared for ${esc(state.user.name)} · 7 October 2026</p><div class="notice">Prototype Report – Not an Official FBR Filing</div></div>${[['Personal Information',`${esc(state.user.name)} · ${esc(state.user.occupation)} · Pakistan`],['Income Summary','Salary Rs. 2,160,000 + freelance Rs. 240,000 = Rs. 2,400,000'],['Expense Summary','Annual sample expenses: Rs. 1,100,000'],['Assets',money(state.assets.reduce((s,a)=>s+a.amount,0))+' · full inventory'],['Liabilities',money(state.liabilities.reduce((s,a)=>s+a.amount,0))+' · full inventory'],['Withholding Tax','Rs. 90,000 · sample employer withholding'],['Tax Calculation','Taxable income Rs. 2,300,000 × illustrative 5% = Rs. 115,000. Less withholding: Rs. 25,000 estimated payable.'],['Wealth Summary',`Separate annual scenario: opening Rs. 2,000,000 · expected ${money(3300000+(state.adjustment||0))} · recorded Rs. 3,250,000`],['Reconciliation Status',`${money(50000+(state.adjustment||0))} difference · ${50000+(state.adjustment||0)===0?'balanced sample':'review required'}`]].map(([n,v])=>`<section style="margin:22px 0"><h3>${n}</h3><p class="muted" style="font-size:12px">${v}</p></section>`).join('')}<small>All figures are illustrative. No information is submitted to FBR. PDF export uses your browser’s Print → Save as PDF.</small></article>`;}
const questions=['How much can I spend this week?','Where did I spend the most?','Why is my budget exceeded?','How much should I save?','How much emergency fund do I need?','Can I afford a Rs. 100,000 purchase?','What recurring expenses do I have?','What information is missing for my tax preparation?','Explain my tax calculation.'];
function assistant(){return heading('A little clarity goes a long way.','Your personal financial companion. Simulated answers using your sample data.')+`<div class="chat"><div class="chat-welcome"><div class="ai-symbol">${icon('spark')}</div><h1>Money questions? You’re in the right place.</h1><p class="muted">Ask in English, Urdu, or Roman Urdu. Let’s make sense of your money.</p></div>${state.chat.length?'':`<div class="suggestions">${questions.map((q,i)=>`<button data-action="ask:${i}">${q} <span style="float:right;color:var(--green)">↗</span></button>`).join('')}</div>`}<div id="messages" aria-live="polite">${state.chat.map(m=>`<div class="message ${m.role}"><strong>${m.role==='user'?'You':'HisabKetab AI · simulated'}</strong>${esc(m.text)}</div>`).join('')}</div><form id="chat-form" class="chat-form"><input name="message" aria-label="Your message" placeholder="Ask anything about your money..." required autocomplete="off"><button type="button" class="icon-btn" aria-label="Simulate voice expense" data-action="voice">${icon('mic')}</button><button type="submit" class="btn primary">${icon('arrow')}<span>Send</span></button></form><p style="text-align:center;font-size:10px" class="muted">Sample insights, not financial or tax advice. No AI service is connected.</p></div>`;}
function notifications(){return heading('You’re all caught up. Almost.','Timely nudges for the things that matter.',btn('Mark all as read','read-all','','check'))+`<section class="card">${state.notifications.map((n,i)=>`<div class="notification ${n.read?'read':''}"><span class="category-icon ${i%2?'blue':'green'}">${icon(n.icon)}</span><div><h3 style="margin:0">${n.title}</h3><p>${n.text}</p><small>7 October 2026 · ${i+1}h ago ${n.read?'· Read':''}</small></div><div class="actions">${link('View',n.route,'btn')}${n.read?'':btn('Mark read',`read:${i}`)}</div></div>`).join('')}</section>`;}
const settingsTabs=['Personal Information','Financial Profile','Tax Profile','Language & Currency','Notifications','Security','Privacy','Data Export','Connected Accounts','Help & Support'];
function settings(){return heading('Make yourself at home.','Your profile, preferences, and everything in between.',`${link('Admin demo','admin','btn')}${btn('Log out','logout','','logout')}`)+`<div class="settings-layout"><nav class="settings-menu" aria-label="Settings">${settingsTabs.map((s,i)=>`<button class="${state.settings===s?'active':''}" data-action="settings:${i}">${s}</button>`).join('')}</nav><section class="card">${cardHead(state.settings)}${settingsContent()}</section></div>`;}
function settingsContent(){switch(state.settings){case 'Personal Information':return `<form id="profile-form"><div class="profile" style="border:0;padding:0;margin-bottom:25px"><span class="avatar" style="width:58px;height:58px;font-size:20px">AA</span><div><h3 style="margin:0">${esc(state.user.name)}</h3><small>Personal account · Pakistan</small></div></div>${field('Full name','name','text',state.user.name,'required')}${field('Email address','email','email',state.user.email,'required')}${field('Occupation','occupation','text',state.user.occupation,'required')}${btn('Save changes','submit-form','primary')}</form>`;case 'Financial Profile':return `<form id="financial-form">${field('Monthly income (PKR)','income','number',state.user.income,'min="0" required')}${selectField('Income type','incomeType',['Salary','Freelance','Business','Rental','Investment','Other'],state.user.incomeType)}<p class="muted">Your profile income is a planning preference; changing it does not create a salary transaction.</p>${btn('Save financial profile','submit-form','primary')}</form>`;case 'Tax Profile':return `<form id="tax-profile-form">${field('CNIC / NTN (sample only)','ntn','text',state.user.ntn||'','placeholder="Enter a fictional identifier" required')}${selectField('Filing status','filing',['Preparing first return','Previously filed','Not sure'],state.user.filing)}${field('Tax residence','residence','text','Pakistan','required')}${btn('Save tax profile','submit-form','primary')}</form>`;case 'Language & Currency':return `<form id="language-form">${selectField('Preferred language','language',['English','Urdu','Roman Urdu'],state.user.language)}${selectField('Currency','currency',['PKR'],'PKR')}<div class="notice info">Language preference is saved for the demo. The primary interface remains in English.</div>${btn('Save preferences','submit-form','primary')}</form>`;case 'Notifications':return Object.entries(state.preferences).map(([n,on],i)=>`<div class="list-line"><span>${n}</span><button class="switch ${on?'on':''}" role="switch" aria-checked="${on}" aria-label="${n}" data-action="toggle-pref:${i}"></button></div>`).join('');case 'Security':return `<p class="muted">Authentication and security controls are demonstrated locally.</p>${btn('Change password','password','primary')}<div class="list-line"><span>Two-step verification (demo)</span><button class="switch ${state.twoStep?'on':''}" role="switch" aria-checked="${!!state.twoStep}" aria-label="Two-step verification" data-action="two-step"></button></div>`;case 'Privacy':return `<p class="muted">Your edits live in memory for this browser session. No financial information is sent to a server. Refreshing restores the sample data.</p><div class="notice info">Voice and receipt processing are simulated. This prototype never requests microphone access.</div>${btn('Clear chat history','clear-chat')}`;case 'Data Export':return `<p class="muted">Download your current transactions, goals, budget, assets, and profile as a JSON file.</p>${btn('Export session data','export-data','primary','download')}`;case 'Connected Accounts':return `<div class="notice info">Demo only. No bank or wallet is connected. No credentials are requested.</div>${['Bank account','Easypaisa','JazzCash'].map(n=>`<div class="list-line"><span>${n}</span><button class="btn" data-action="connect:${n}">${state.connected?.includes(n)?'Disconnect demo':'Connect demo'}</button></div>`).join('')}`;default:return `<h3>Welcome to the HisabKetab AI prototype</h3><p class="muted">Use Add transaction for manual entry, simulated voice capture, or receipt scanning. Explore the AI tabs within Budget, Goals, and Tax to demonstrate the five project capabilities.</p><details class="details-step"><summary>Is my data saved?</summary><p>No. Data is kept in memory and resets on refresh.</p></details><details class="details-step"><summary>Does the app file my tax return?</summary><p>No. Reports and tax rules are illustrative and are never sent to FBR.</p></details>${link('Replay onboarding','splash','btn')}`;}}
function admin(){return heading('Behind the experience.','A local admin demonstration. Changes are session-only.',link('Back to settings','settings','btn'))+`<div class="stats">${[['Total users','1,248'],['Active users','986'],['Transactions',String(state.transactions.length)],['Tax-year rules',String(state.admin.rules.length)]].map(([n,v])=>`<div class="stat"><div class="stat-label">${n}${icon('settings')}</div><div class="amount">${v}</div><small>Prototype sample</small></div>`).join('')}</div><div class="two-grid">${[['categories','Expense categories'],['rules','Tax-year rules'],['templates','Notification templates']].map(([key,n])=>`<section class="card">${cardHead(n,'Manage local demo entries.',btn('Add',`admin-add:${key}`,'','plus'))}${state.admin[key].map((v,i)=>`<div class="list-line"><span>${esc(v)}</span><button class="icon-btn" aria-label="Edit ${esc(v)}" data-action="admin-edit:${key}:${i}">${icon('edit')}</button></div>`).join('')}</section>`).join('')}<section class="card">${cardHead('System configuration','Recurring rule configuration & system notifications')}<form id="admin-config">${field('Recurring confidence threshold (%)','confidence','number',state.admin.config['Recurring confidence threshold'],'min="0" max="100" required')}${field('Budget alert threshold (%)','threshold','number',state.admin.config['Budget alert threshold'],'min="0" max="100" required')}${btn('Save configuration','submit-form','primary')}</form></section></div>`;}
function scanPage(){return heading('Less typing. More living.','Scan a receipt and review the details before adding it.')+`<section class="card" style="max-width:700px;margin:auto"><div class="upload-zone">${icon('scan')}<h2 style="margin-top:20px">Turn a receipt into a transaction.</h2><p class="muted">Upload an image or use the sample receipt to try the simulated flow.</p><div class="actions" style="justify-content:center">${btn('Take photo','take-photo','','scan')}${btn('Upload receipt','upload-receipt','','plus')}${btn('Try sample receipt','sample-receipt','primary')}</div><input id="receipt-file" type="file" accept="image/*" hidden><input id="receipt-camera" type="file" accept="image/*" capture="environment" hidden></div><small>OCR is simulated. Uploaded images are not transmitted or analyzed.</small></section>`;}
const pages={home,transactions,budget,adaptive,recurring,goals,allocation,emergency,insights,health,assets,tax,reasoning,reconciliation,report,assistant,notifications,settings,admin,scan:scanPage};
function options(list,value,allLabel){return list.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v==='All'&&allLabel?allLabel:v)}</option>`).join('');}
function field(label,name,type='text',value='',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function selectField(label,name,list,value){return `<label class="field">${label}<select name="${name}">${options(list,value)}</select></label>`;}
function showModal(title,body){previousFocus=document.activeElement;const m=$('#modal');m.innerHTML=`<div class="modal-heading"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${body}`;if(!m.open)m.showModal();}
function closeModal(){clearInterval(recordTimer);clearTimeout(simulationTimer);$('#modal').close();previousFocus?.focus?.();}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('toast-visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('toast-visible'),3300);}
function saveDone(message){closeModal();render();toast(message);}
function transactionForm(id,seed){const t=seed||state.transactions.find(t=>t.id===Number(id))||{type:'Expense',amount:'',category:'Food',date:'2026-10-07',payment:'Cash',merchant:'',person:'',notes:'',recurring:false};showModal(id?'Edit transaction':'Add a transaction',`<form id="transaction-form" data-id="${id||''}"><div class="form-grid">${selectField('Transaction type','type',['Expense','Income'],t.type)}${field('Amount (PKR)','amount','number',t.amount,'min="1" step="0.01" required')}${selectField('Category','category',categories,t.category)}${field('Date','date','date',t.date,'required')}${selectField('Payment method','payment',payments,t.payment)}${field('Merchant / title','merchant','text',t.merchant,'required maxlength="100"')}${field('Person (optional)','person','text',t.person||'')}${selectField('Recurring','recurring',['No','Yes'],t.recurring?'Yes':'No')}<label class="field full">Notes<textarea name="notes">${esc(t.notes||'')}</textarea></label></div><div class="modal-footer">${btn('Cancel','close-modal')}<button class="btn primary" type="submit">${id?'Save changes':'Add transaction'}</button></div></form>`);}
function transactionDetails(id){const t=state.transactions.find(t=>t.id===Number(id));if(!t)return;showModal(esc(t.merchant),`<div class="big-number">${t.type==='Income'?'+':'−'} ${money(t.amount)}</div>${[['Type',t.type],['Category',t.category],['Date',dateLabel(t.date)],['Payment',t.payment],['Person',t.person||'—'],['Recurring',t.recurring?'Yes':'No'],['Notes',t.notes||'—']].map(([n,v])=>`<div class="list-line"><span class="muted">${n}</span><strong>${esc(v)}</strong></div>`).join('')}<div class="actions" style="margin-top:24px">${btn('Edit',`edit-transaction:${id}`,'primary','edit')}${btn('Duplicate',`duplicate:${id}`)}${btn(t.recurring?'Remove recurring':'Mark recurring',`toggle-recurring:${id}`)}${btn('Delete',`delete-transaction:${id}`,'danger')}</div>`);}
function goalForm(id){const g=state.goals.find(g=>g.id===Number(id))||{name:'',target:'',saved:0,date:'2027-10-01',priority:'Medium'};showModal(id?'Edit your goal':'What are you saving for?',`<form id="goal-form" data-id="${id||''}">${field('Goal name','name','text',g.name,'required maxlength="60"')}<div class="form-grid">${field('Target amount (PKR)','target','number',g.target,'min="1" required')}${field('Current savings (PKR)','saved','number',g.saved,'min="0" required')}${field('Target date','date','date',g.date,'required')}${selectField('Priority','priority',['High','Medium','Low'],g.priority)}</div><div class="modal-footer">${btn('Cancel','close-modal')}<button class="btn primary">Save goal</button></div></form>`);}
function recurringForm(id){const r=state.recurring.find(r=>r.id===Number(id))||{name:'',amount:'',date:'2026-11-01'};showModal(id?'Edit recurring obligation':'Add recurring obligation',`<form id="recurring-form" data-id="${id||''}">${field('Name','name','text',r.name,'required')}${field('Monthly amount (PKR)','amount','number',r.amount,'required min="1"')}${field('Next payment','date','date',r.date,'required')}<button class="btn primary">Save obligation</button></form>`);}
function voice(){voiceStage='idle';showModal('Let’s hear your expense.',`<div class="capture"><span class="pill">VOICE SIMULATION</span><p style="margin-top:17px">Speak naturally. We’ll help with the details.</p><button class="record-button" id="record-button" aria-label="Hold to record; release to process">${icon('mic')}</button><div class="recording-label" id="record-label">Hold to Record</div><p id="record-time">00:00</p><p>Hold the button or press and hold Space.<br>No microphone access is needed.</p><p><em>“I spent Rs. 500 on petrol by cash and Rs. 6000 on food with Ali. I paid half by card.”</em></p>${btn('Play sample recording','voice-sample','','mic')}</div>`);}
function startRecording(){if(voiceStage!=='idle')return;voiceStage='recording';recordStarted=Date.now();$('#record-button')?.classList.add('recording');if($('#record-label'))$('#record-label').textContent='Recording...';recordTimer=setInterval(()=>{if($('#record-time'))$('#record-time').textContent='00:'+String(Math.floor((Date.now()-recordStarted)/1000)).padStart(2,'0');},200);}
function finishRecording(){if(voiceStage!=='recording')return;voiceStage='processing';clearInterval(recordTimer);showModal('Understanding your financial statement...',`<div class="capture"><div class="loading"></div><h3>Finding the details in your words.</h3><p>Simulated processing · no audio is recorded.</p></div>`);simulationTimer=setTimeout(()=>{voiceStage='review';showModal('Two expenses. All figured out.',`<span class="pill">REVIEW AI EXTRACTION</span><p class="muted" style="margin-top:15px">“I spent Rs. 500 on petrol by cash and Rs. 6000 on food with Ali. I paid half by card.”</p><form id="voice-form"><div class="card" style="margin:15px 0"><h3>Transaction 1 · Petrol</h3><div class="form-grid">${field('Your expense (PKR)','petrol','number',500,'min="1" required readonly')}${selectField('Payment','petrolPayment',payments,'Cash')}</div></div><div class="card"><h3>Transaction 2 · Food with Ali</h3><p class="muted">Total shared: Rs. 6,000 · split equally with Ali</p><div class="form-grid">${field('Your share (PKR)','food','number',3000,'min="1" max="6000" required readonly')}${selectField('Payment','foodPayment',payments,'Card')}</div></div><div class="modal-footer">${btn('Edit','edit-voice','','edit')}<button class="btn primary" type="submit">Confirm all</button></div></form>`);},1100);}
function processReceipt(file){if(file&&!file.type.startsWith('image/')){toast('Please select an image file.');return;}showModal('Extracting information...',`<div class="capture"><div class="loading"></div><p>Reading a sample receipt. ${file?esc(file.name):'ABC Super Store'}</p><small>OCR simulation · image contents are not analyzed.</small></div>`);simulationTimer=setTimeout(()=>showModal('Receipt ready for review',`<span class="pill">SIMULATED RECEIPT</span><form id="receipt-form"><div class="receipt-paper" style="margin-top:17px"><h3>ABC SUPER STORE</h3><p style="text-align:center" class="muted">06 Oct 2026 · Islamabad</p>${[['Milk',250],['Bread',180],['Snacks',300],['Subtotal',730],['Tax',73]].map(([n,v])=>`<div class="list-line"><span>${n}</span><strong>${money(v)}</strong></div>`).join('')}<div class="list-line"><strong>Total</strong><strong>Rs. 803</strong></div></div><div class="form-grid" style="margin-top:20px">${field('Merchant','merchant','text','ABC Super Store','required readonly')}${field('Date','date','date','2026-10-06','required readonly')}${field('Total (PKR)','amount','number',803,'min="1" required readonly')}${selectField('Payment','payment',payments,'Card')}</div><div class="modal-footer">${btn('Edit','edit-receipt','','edit')}<button class="btn primary">Confirm transaction</button></div></form>`),1100);}
function aiAnswer(q){const s=q.toLowerCase(),t=totals();if(/tax|fbr|ٹیکس/.test(s))return /missing|information/.test(s)?`Your draft tax profile is ${state.taxDocs.length?92:82}% complete. ${state.taxDocs.length?'Your sample document is added. Review your CNIC / NTN and reconciliation difference.':'Add your withholding certificate and review your CNIC / NTN.'} These are sample preparation checks, not a filing.`:'In our illustrative scenario, Rs. 2,400,000 income minus Rs. 100,000 adjustments gives Rs. 2,300,000 taxable income. A demo 5% rate gives Rs. 115,000; deduct Rs. 90,000 withholding to get Rs. 25,000. This is not an official tax slab. Explore Tax → How it’s calculated.';if(/emergency|ہنگامی/.test(s))return `Your sample emergency fund recommendation is ${money(state.emergency?.recommended||450000)}. You have ${money(state.goals[0].saved)} saved. This considers essential expenses, recurring commitments, and income stability.`;if(/recurr|bill|regular/.test(s))return 'Your recurring obligations are '+state.recurring.filter(r=>r.status!=='Ignored').map(r=>`${r.name}: ${money(r.amount)} monthly`).join('; ')+'. Review and confirm the detected suggestions under Budget → Recurring obligations.';if(/afford|purchase|100,000|100000/.test(s))return `Your available balance is ${money(t.balance)}, but your remaining monthly budget is ${money(t.remaining)}. A Rs. 100,000 purchase would exceed that budget. Consider saving toward it as a separate goal.`;if(/most|where|زیادہ/.test(s)){const sums={};state.transactions.filter(t=>t.type==='Expense').forEach(t=>sums[t.category]=(sums[t.category]||0)+t.amount);const top=Object.entries(sums).sort((a,b)=>b[1]-a[1])[0];return `Your largest category in the current transaction list is ${top[0]} at ${money(top[1])}. Use Transactions to review the entries behind that total.`;}if(/exceed|over|budget/.test(s))return `You have spent ${money(t.expenses)} of your ${money(state.budget)} monthly budget. Shopping is ${money(Math.max(0,budgetValues()[2][1]-budgetValues()[2][2]))} over its category limit. Your sample daily discretionary allowance is ${money(dailyLimit())}.`;if(/sav|goal|بچت/.test(s))return `Your sample monthly surplus is ${money(state.surplus)}. The recommended allocation is ${money(state.allocation[0])} to your emergency fund, ${money(state.allocation[1])} to your car, and ${money(state.allocation[2])} to vacation. Review this under Goals → Goal allocation.`;if(/week|spend|kharch|خرچ/.test(s))return `Your remaining monthly budget is ${money(t.remaining)}. In the sample 12-day planning scenario, after reserved obligations and savings, aim for ${money(dailyLimit())} a day or ${money(dailyLimit()*7)} over seven days.`;return `I can help explain your sample spending, budget, goals, recurring payments, or tax preparation. You currently have ${money(t.balance)} available and ${money(t.remaining)} left in your monthly budget. Try “How much can I spend this week?”`;}
function ask(q){state.chat.push({role:'user',text:q});render();$('#messages')?.scrollIntoView({block:'end'});const answer=aiAnswer(q);setTimeout(()=>{state.chat.push({role:'assistant',text:answer});if(route==='assistant'){render();$('#messages')?.scrollIntoView({block:'end'});$('#chat-form input')?.focus();}},650);}
function downloadData(){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='hisabketab-demo-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Session data exported.');}
function renderAuth(){if(route==='splash'){$('#app').innerHTML=`<main class="splash">${brand()}<p>Your money, a little smarter.</p><div class="loading"></div><small style="color:#d0e3d6">Personal finance, made personal.</small></main>`;setTimeout(()=>{if(location.hash==='#splash')location.hash='login';},1000);return;}let title='Welcome back.',description='Your next good money decision starts here.',form='';if(route==='login'){form=`<form id="login-form">${field('Email address','email','email','abubakar.awan@example.com','required autocomplete="username"')}${field('Password','password','password','demo1234','required autocomplete="current-password"')}<div class="split"><label class="check-row"><input type="checkbox" checked> Remember me</label>${link('Forgot password?','forgot','text-btn')}</div><button class="btn primary">Log in ${icon('arrow')}</button></form><p class="auth-footer">New here? <a class="text-btn" href="#signup">Create an account</a></p>${link('Explore the demo','home','btn')}`;}if(route==='signup'){title='Your better money story starts here.';description='Create your sample account. No real registration needed.';form=`<form id="signup-form">${field('Full name','name','text','','required autocomplete="name"')}${field('Email address','email','email','','required autocomplete="email"')}${field('Password','password','password','','required minlength="6" autocomplete="new-password"')}<label class="check-row"><input type="checkbox" required>I understand this is a frontend demonstration.</label><button class="btn primary">Create account</button></form><p class="auth-footer">Already have an account? ${link('Log in','login','text-btn')}</p>`;}if(route==='otp'){title='Check your inbox. In theory.';description='No email is sent. Enter the demo code 123456 to continue.';form=`<form id="otp-form">${field('Verification code','otp','text','','required pattern="123456" inputmode="numeric" maxlength="6" autocomplete="one-time-code" title="Use demo code 123456"')}<button class="btn primary">Verify & continue</button></form>${btn('Resend demo code','resend-otp')}`;}if(route==='forgot'){title='Let’s get you back in.';description='Try the password recovery flow. No email will be sent.';form=`<form id="forgot-form">${field('Email address','email','email','','required')}<button class="btn primary">Send reset link</button></form>${link('Back to login','login','btn')}`;}if(route==='onboarding'){title='A little about you.';description='A more personal plan starts with a few details.';form=`<form id="onboarding-form">${field('Full name','name','text',state.user.name,'required')}${field('Occupation','occupation','text',state.user.occupation,'required')}${field('Monthly income (PKR)','income','number',state.user.income,'required min="0"')}${selectField('Income type','incomeType',['Salary','Freelance','Business','Rental','Investment','Other'],state.user.incomeType)}${selectField('Main financial goal','mainGoal',['Build an emergency fund','Buy a car','Save for travel','Manage my tax','Reduce debt'],'Build an emergency fund')}<button class="btn primary">Let’s get started ${icon('arrow')}</button></form>`;}$('#app').innerHTML=`<main class="auth"><section class="auth-art">${brand()}<div><div class="eyebrow" style="color:#acd19f">A LITTLE CLARITY. A LOT OF POSSIBILITY.</div><h1>Your money.<br>Your future.<br>A smarter way.</h1><p>Bring your spending, savings, and tax preparation together. Built around life in Pakistan.</p><div class="auth-orbit"><span class="brand-mark">${icon('insights')}</span></div></div><small style="color:#adc9bc">Designed for your everyday. And your someday.</small></section><section class="auth-form"><div class="auth-form-inner">${brand()}<h1>${title}</h1><p class="muted" style="margin-bottom:28px">${description}</p>${form}<div class="auth-footer">Frontend prototype · No real authentication<br>All your demo data stays in this session.</div></div></section></main>`;}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target)return;const [action,a,b]=target.dataset.action.split(':');switch(action){case 'menu':$('.sidebar').classList.toggle('mobile-open');break;case 'close-modal':closeModal();break;case 'submit-form':target.closest('form').requestSubmit();break;case 'date':showModal('Your October overview','<p class="muted">This prototype uses a fixed October 2026 sample period. Use date filters on Transactions to explore the entries.</p>'+link('Explore transactions','transactions','btn primary'));break;case 'quick-add':showModal('How would you like to add it?',`<p class="muted">A quick note, a receipt, or a few details. Your choice.</p><div class="three-grid">${btn('Voice','voice','primary','mic')}${btn('Scan receipt','scan','','scan')}${btn('Manual entry','manual','','edit')}</div>`);break;case 'manual':transactionForm();break;case 'scan':closeModal();location.hash='scan';break;case 'transaction':transactionDetails(a);break;case 'edit-transaction':transactionForm(a);break;case 'duplicate':{const t=state.transactions.find(t=>t.id===+a);state.transactions.push({...t,id:Date.now(),merchant:t.merchant+' (copy)'});saveDone('Transaction duplicated.');break;}case 'toggle-recurring':{const t=state.transactions.find(t=>t.id===+a);t.recurring=!t.recurring;saveDone('Recurring preference updated.');break;}case 'delete-transaction':showModal('Delete this transaction?',`<p>This removes the transaction from this demo session and updates your totals.</p><div class="modal-footer">${btn('Cancel','close-modal')}${btn('Delete transaction',`confirm-delete:${a}`,'danger')}</div>`);break;case 'confirm-delete':state.transactions=state.transactions.filter(t=>t.id!==+a);saveDone('Transaction deleted.');break;case 'reset-filters':state.filter={search:'',type:'All',category:'All',payment:'All',from:'',to:'',sort:'newest'};render();break;case 'period':state.period=a;render();break;case 'edit-budget':showModal('Give your spending a plan.',`<form id="budget-form">${field('Monthly budget (PKR)','monthly','number',state.budget,'min="1" required')}${field('Weekly budget (PKR)','weekly','number',state.weeklyBudget,'min="1" required')}<button class="btn primary">Save budget</button></form>`);break;case 'category-budgets':showModal('Category spending limits',`<form id="category-budget-form">${budgetValues().map(([n,v,m])=>field(n+' (PKR)',n,'number',m,'min="1" required')).join('')}<button class="btn primary">Save limits</button></form>`);break;case 'calculation':showModal('A transparent daily plan',`<p class="muted">Sample scenario: 12 days remaining.</p>${[['Remaining budget',totals().remaining],['Less reserved obligations',7600],['Less savings target',5000],['Available discretionary amount',Math.max(0,totals().remaining-12600)],['Daily limit (divide by 12)',dailyLimit()]].map(([n,v])=>`<div class="list-line"><span>${n}</span><strong>${money(v)}</strong></div>`).join('')}<div class="notice info">This illustrative forecast is calculated with JavaScript. It is not a prediction from an AI model.</div>`);break;case 'add-recurring':recurringForm();break;case 'edit-recurring':recurringForm(a);break;case 'confirm-recurring':state.recurring.find(r=>r.id===+a).status='Confirmed';render();toast('Obligation confirmed.');break;case 'ignore-recurring':state.recurring.find(r=>r.id===+a).status='Ignored';render();toast('Suggestion ignored.');break;case 'restore-recurring':state.recurring.forEach(r=>{if(r.status==='Ignored')r.status='Detected';});render();break;case 'create-goal':goalForm();break;case 'edit-goal':goalForm(a);break;case 'fund-goal':showModal('A step closer to your goal.',`<form id="fund-form" data-id="${a}">${field('Add savings (PKR)','amount','number','','required min="1"')}<p class="muted">Updates your goal’s tracked savings only. No money is transferred.</p><button class="btn primary">Add savings</button></form>`);break;case 'accept-allocation':state.allocated=true;render();toast('Monthly allocation saved. No funds transferred.');break;case 'modify-allocation':showModal('Make the plan your own.',`<form id="allocation-form"><p>Monthly surplus: <strong>${money(state.surplus)}</strong></p>${state.goals.slice(0,3).map((g,i)=>field(g.name+' (PKR)','allocation'+i,'number',state.allocation[i],'required min="0" step="1"')).join('')}<p id="allocation-error" role="alert" style="color:var(--red)"></p><button class="btn primary">Save allocation</button></form>`);break;case 'add-asset':case 'edit-asset':{const item=action==='edit-asset'?state[a].find(x=>x.id===+b):{name:'',amount:''};showModal(action==='add-asset'?'Add an asset or liability':'Update your balance',`<form id="asset-form" data-id="${b||''}" data-key="${a||''}">${selectField('Type','key',['assets','liabilities'],a||'assets')}${field('Name','name','text',item.name,'required')}${field('Value (PKR)','amount','number',item.amount,'required min="0"')}<button class="btn primary">Save item</button></form>`);break;}case 'tax-year':toast('The prototype includes the illustrative 2026 tax year.');break;case 'tax-document':showModal('Add a sample tax document',`<form id="document-form"><label class="field">Document file<input name="document" type="file" accept=".pdf,image/*" required></label><p class="muted">Only the filename is kept in the demo. Nothing is uploaded.</p><button class="btn primary">Add document</button></form>`);break;case 'adjust-reconciliation':showModal('Review annual adjustments',`<form id="reconcile-form">${field('Adjustment (PKR)','adjustment','number',state.adjustment||0,'required')}<p class="muted">Example: a −Rs. 50,000 adjustment balances this annual sample. Verify the reason before applying.</p>${field('Reason','reason','text',state.adjustmentReason||'','required')}<button class="btn primary">Apply adjustment</button></form>`);break;case 'preview-report':$('#report').scrollIntoView({behavior:'smooth'});toast('Report preview is shown below.');break;case 'print-report':window.print();break;case 'ask':ask(questions[+a]);break;case 'read-all':state.notifications.forEach(n=>n.read=true);render();toast('All notifications marked as read.');break;case 'read':state.notifications[+a].read=true;render();break;case 'settings':state.settings=settingsTabs[+a];render();break;case 'toggle-pref':{const key=Object.keys(state.preferences)[+a];state.preferences[key]=!state.preferences[key];render();break;}case 'two-step':state.twoStep=!state.twoStep;render();toast('Demo security preference updated.');break;case 'password':showModal('Change demo password',`<form id="password-form">${field('New password','password','password','','minlength="6" required autocomplete="new-password"')}${field('Confirm password','confirm','password','','minlength="6" required autocomplete="new-password"')}<p id="password-error" role="alert" style="color:var(--red)"></p><button class="btn primary">Update demo password</button></form>`);break;case 'clear-chat':state.chat=[];toast('Chat history cleared.');break;case 'export-data':downloadData();break;case 'connect':state.connected=state.connected||[];state.connected=state.connected.includes(a)?state.connected.filter(n=>n!==a):[...state.connected,a];render();toast('Demo connection updated. No account was accessed.');break;case 'logout':location.hash='login';toast('Logged out of the demo.');break;case 'admin-add':case 'admin-edit':showModal('Manage demo entry',`<form id="admin-entry-form" data-key="${a}" data-index="${b??''}">${field('Name / rule / template','value','text',b!==undefined?state.admin[a][+b]:'','required maxlength="180"')}<div class="modal-footer">${b!==undefined?btn('Delete entry',`admin-delete:${a}:${b}`,'danger'):''}<button class="btn primary">Save entry</button></div></form>`);break;case 'admin-delete':state.admin[a].splice(+b,1);saveDone('Admin entry removed.');break;case 'voice':voice();break;case 'voice-sample':startRecording();simulationTimer=setTimeout(finishRecording,1300);break;case 'edit-voice':$('#voice-form').querySelectorAll('[readonly]').forEach(n=>n.removeAttribute('readonly'));$('#voice-form input').focus();toast('You can now edit the extracted amounts.');break;case 'take-photo':$('#receipt-camera').click();break;case 'upload-receipt':$('#receipt-file').click();break;case 'sample-receipt':processReceipt();break;case 'edit-receipt':$('#receipt-form').querySelectorAll('[readonly]').forEach(n=>n.removeAttribute('readonly'));$('#receipt-form input').focus();toast('Receipt details are editable.');break;case 'resend-otp':toast('Demo verification code: 123456. No email sent.');break;}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));switch(f.id){case 'global-search':state.filter.search=d.search;location.hash='transactions';if(route==='transactions')render();break;case 'transaction-form':{const t={...d,id:f.dataset.id?+f.dataset.id:Date.now(),amount:+d.amount,recurring:d.recurring==='Yes'};if(f.dataset.id)state.transactions=state.transactions.map(x=>x.id===t.id?t:x);else state.transactions.push(t);saveDone('Transaction saved. Your balances are up to date.');break;}case 'budget-form':state.budget=+d.monthly;state.weeklyBudget=+d.weekly;saveDone('Your budget has been updated.');break;case 'category-budget-form':state.categoryBudgets=Object.fromEntries(Object.entries(d).map(([k,v])=>[k,+v]));saveDone('Category limits updated.');break;case 'goal-form':{const g={...d,id:f.dataset.id?+f.dataset.id:Date.now(),target:+d.target,saved:+d.saved,icon:'goals'};if(f.dataset.id)state.goals=state.goals.map(x=>x.id===g.id?{...x,...g}:x);else state.goals.push(g);saveDone('Your goal is ready.');break;}case 'fund-form':state.goals.find(g=>g.id===+f.dataset.id).saved+=+d.amount;saveDone('Savings added to your goal.');break;case 'recurring-form':{const r={...d,id:f.dataset.id?+f.dataset.id:Date.now(),amount:+d.amount,confidence:100,status:'Confirmed'};if(f.dataset.id)state.recurring=state.recurring.map(x=>x.id===r.id?{...x,...r}:x);else state.recurring.push(r);saveDone('Recurring obligation saved.');break;}case 'allocation-form':{const arr=[+d.allocation0,+d.allocation1,+d.allocation2];if(arr.reduce((s,v)=>s+v,0)!==state.surplus){$('#allocation-error').textContent='Allocations must add up to '+money(state.surplus)+'.';break;}state.allocation=arr;state.allocated=true;saveDone('Your allocation has been saved.');break;}case 'emergency-form':{const months={High:3,Medium:5,Low:6};state.emergency={essential:+d.essential,obligations:+d.obligations,stability:d.stability,recommended:Math.ceil((+d.essential+.5*d.obligations)*months[d.stability]/50000)*50000};render();toast('Emergency fund estimate updated.');break;}case 'asset-form':{const item={id:f.dataset.id?+f.dataset.id:Date.now(),name:d.name,amount:+d.amount};if(f.dataset.id)state[f.dataset.key]=state[f.dataset.key].filter(x=>x.id!==item.id);state[d.key].push(item);saveDone('Your wealth inventory is updated.');break;}case 'document-form':state.taxDocs.push(f.elements.document.files[0].name);saveDone('Sample document added to your tax checklist.');break;case 'reconcile-form':state.adjustment=+d.adjustment;state.adjustmentReason=d.reason;saveDone('Annual adjustment applied.');break;case 'chat-form':if(d.message.trim())ask(d.message.trim());break;case 'profile-form':case 'financial-form':case 'tax-profile-form':case 'language-form':Object.assign(state.user,d);render();toast('Your preferences have been saved.');break;case 'password-form':if(d.password!==d.confirm){$('#password-error').textContent='Passwords do not match.';break;}saveDone('Demo password flow completed. No credentials stored.');break;case 'admin-config':state.admin.config={'Recurring confidence threshold':+d.confidence,'Budget alert threshold':+d.threshold};toast('Demo configuration saved.');break;case 'admin-entry-form':if(f.dataset.index!=='')state.admin[f.dataset.key][+f.dataset.index]=d.value;else state.admin[f.dataset.key].push(d.value);saveDone('Demo entry saved.');break;case 'voice-form':state.transactions.push({id:Date.now(),type:'Expense',merchant:'Petrol',category:'Petrol/Transport',amount:+d.petrol,payment:d.petrolPayment,date:'2026-10-07',notes:'Simulated voice entry',recurring:false},{id:Date.now()+1,type:'Expense',merchant:'Food with Ali',category:'Food',amount:+d.food,payment:d.foodPayment,date:'2026-10-07',person:'Ali',notes:'Shared total Rs. 6,000. Your share: '+money(d.food),recurring:false});saveDone('Both expenses added. Only your share was counted.');break;case 'receipt-form':state.transactions.push({id:Date.now(),type:'Expense',merchant:d.merchant,category:'Shopping',amount:+d.amount,payment:d.payment,date:d.date,notes:'Simulated receipt: Milk Rs. 250, Bread Rs. 180, Snacks Rs. 300, tax Rs. 73.',recurring:false});saveDone('Receipt confirmed. Transaction added.');break;case 'login-form':location.hash='home';break;case 'signup-form':state.user.name=d.name;state.user.email=d.email;location.hash='otp';break;case 'otp-form':location.hash='onboarding';break;case 'forgot-form':showModal('Your demo reset link is ready.',`<p class="muted">No email has been sent. This completes the simulated recovery step for ${esc(d.email)}.</p>${btn('Set a demo password','password','primary')}${link('Back to login','login','btn')}`);break;case 'onboarding-form':Object.assign(state.user,d);location.hash='home';toast('Welcome, '+state.user.name.split(' ')[0]+'. Let’s make a plan.');break;}});
document.addEventListener('change',e=>{if(e.target.dataset.filter){state.filter[e.target.dataset.filter]=e.target.value;render();}if(e.target.id==='chart-period'){state.chart=e.target.value;render();}if(['receipt-file','receipt-camera'].includes(e.target.id)&&e.target.files.length)processReceipt(e.target.files[0]);});
document.addEventListener('input',e=>{if(e.target.id==='transaction-search'){const position=e.target.selectionStart;state.filter.search=e.target.value;render();const el=$('#transaction-search');el.focus();el.setSelectionRange(position,position);}});
document.addEventListener('pointerdown',e=>{if(e.target.closest('#record-button')){e.preventDefault();startRecording();}});
document.addEventListener('pointerup',()=>{if(voiceStage==='recording')finishRecording();});
document.addEventListener('pointercancel',()=>{if(voiceStage==='recording')finishRecording();});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search input')?.focus();}if(e.target.id==='record-button'&&(e.key===' '||e.key==='Enter')){e.preventDefault();if(!e.repeat)startRecording();}});
document.addEventListener('keyup',e=>{if(e.target.id==='record-button'&&(e.key===' '||e.key==='Enter')){e.preventDefault();finishRecording();}});
$('#modal').addEventListener('cancel',()=>{clearInterval(recordTimer);clearTimeout(simulationTimer);voiceStage='idle';});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{if($('#modal').open)closeModal();render();window.scrollTo(0,0);});
render();
